  last: number
  dayPct: number
  stance: CommodityStance
  related?: string
}

export interface CommoditiesBlock {
  oil: CommodityQuote
  gold: CommodityQuote
  silver: CommodityQuote
}

export interface SignalCard {
  symbol: string
  side: SignalSide
  open: number
  prevClose: number
  last: number
  dayPct: number
  rationale: string
}

export interface PortfolioRecommendation {
