  font-weight: 600;
  padding: 2px 8px;
  border-radius: 100px;
  background: var(--etoro-card);
  border: 1px solid var(--etoro-border-subtle);
  color: var(--etoro-text-muted);
}

.tqa-rationale {
  margin: 4px 0 6px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--etoro-text);
}

.tqa-reasons {
  margin: 0 0 6px;
  padding-left: 18px;
  font-size: 12px;
  line-height: 1.45;
  color: var(--etoro-text-muted);
}

.tqa-deviation {
  margin: 0 0 6px;
  font-size: 12px;
  color: var(--etoro-red, #c45c5c);
}

.tqa-deviation code,
.tqa-code-chip,
.tqa-case-id {
  font-family: var(--font-mono);
  font-size: 11px;
  background: var(--etoro-card);
  padding: 2px 6px;
  border-radius: 4px;
  color: var(--etoro-green-light);
}

.tqa-timestamps {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 11px;
  color: var(--etoro-text-dim);
}

.tqa-lessons-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.tqa-lessons-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.tqa-counts {
  font-size: 12px;
  color: var(--etoro-text-muted);
}

.tqa-section-label {
  display: block;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--etoro-text-dim);
  margin-bottom: 6px;
}

.tqa-code-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tqa-lessons-cols {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.tqa-col-title {
  margin: 0 0 8px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.4px;
}

.tqa-col-keep {
  color: var(--etoro-green-light);
}

.tqa-col-avoid {
  color: var(--etoro-red, #c45c5c);
}

.tqa-lesson-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tqa-lesson-item {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  font-size: 12px;
  line-height: 1.45;
}

.tqa-lesson-text {
  color: var(--etoro-text);
}

.tqa-tag {
  flex-shrink: 0;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.4px;
  padding: 2px 7px;
  border-radius: 100px;
}

.tqa-tag-keep {
  color: #0b1a0f;
  background: var(--etoro-green);
}

.tqa-tag-avoid {
  color: #fff;
  background: var(--etoro-red, #c45c5c);
}

.tqa-tag-watch {
  color: #1a1200;
  background: #f9a825;
}

.tqa-tag-note {
  color: var(--etoro-text-muted);
  background: var(--etoro-card);
  border: 1px solid var(--etoro-border);
}

.tqa-case-score {
  margin-left: auto;
  font-size: 14px;
  font-weight: 800;
  font-family: var(--font-mono);
  color: var(--etoro-green-light);
}

@media (max-width: 960px) {
  .tqa-grid,
  .tqa-lessons-cols {
    grid-template-columns: 1fr;
  }

  .app-view-nav {
    padding: 10px 16px 0;
  }
}
EOF

# Inject script patterned on inject-daily-brief.mjs
cat > /workspace/etoroview/scripts/inject-trading-qa.mjs << 'EOF'
#!/usr/bin/env node
/**
 * Inject trading-qa feed into public/trading-qa.json
 * Usage: node scripts/inject-trading-qa.mjs <qa.json>
 *        cat qa.json | node scripts/inject-trading-qa.mjs
 * Vite serves public/ — no rebuild; refresh QA & Lessons view.
 */
import { readFileSync, writeFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..")
const DEST = join(ROOT, "public", "trading-qa.json")

async function readInput() {
  const arg = process.argv[2]
  if (arg && arg !== "-") return readFileSync(arg, "utf8")
  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  const text = Buffer.concat(chunks).toString("utf8").trim()
  if (!text) {
    console.error("Usage: node scripts/inject-trading-qa.mjs <qa.json>")
    process.exit(1)
  }
  return text
}

const raw = await readInput()
let data
try {
  data = JSON.parse(raw)
} catch (e) {
  console.error("Invalid JSON:", e.message)
  process.exit(1)
}

if (!data?.schemaVersion) {
  console.error("Refusing inject: missing schemaVersion")
  process.exit(1)
}
if (!Array.isArray(data.portfolios)) {
  console.error("Refusing inject: missing portfolios[]")
  process.exit(1)
}

const keys = new Set(data.portfolios.map((p) => p?.key).filter(Boolean))
if (keys.has("classic") && keys.has("momentum")) {
  // ok — keep books separate in UI
} else if (data.portfolios.length === 0) {
  console.error("Refusing inject: portfolios[] is empty")
  process.exit(1)
}

writeFileSync(DEST, JSON.stringify(data, null, 2) + "\n")
console.log("Injected trading-qa →", DEST)
console.log(`  schema=${data.schemaVersion} asOf=${data.asOf ?? "—"} portfolios=${data.portfolios.length}`)
for (const p of data.portfolios) {
  const actions = Array.isArray(p.actions) ? p.actions.length : 0
  const days = Array.isArray(p.days) ? p.days.length : 0
  const cases = Array.isArray(p.classicCases) ? p.classicCases.length : 0
  console.log(`  · ${p.key}: actions=${actions} days=${days} classicCases=${cases}`)
}
console.log("Refresh QA & Lessons (#/qa) — no rebuild needed.")
EOF
chmod +x /workspace/etoroview/scripts/inject-trading-qa.mjs

# Add npm script
python3 << 'PY'
from pathlib import Path
import json
p = Path('/workspace/etoroview/package.json')
data = json.loads(p.read_text())
data['scripts']['inject:trading-qa'] = 'node scripts/inject-trading-qa.mjs'
p.write_text(json.dumps(data, indent=2) + '\n')
print('package.json scripts:', data['scripts'])
PY
